:root {
  --primary: oklch(70% 0.18 230);
  --primary-hover: color-mix(in oklab, var(--primary), black 12%);
  --primary-soft:  color-mix(in oklab, var(--primary), white 70%);
  --primary-30:    color-mix(in oklab, var(--primary) 30%, transparent);
}

.btn { background: var(--primary); }
.btn:hover { background: var(--primary-hover); }

.chip {
  color: var(--primary);
  border: 1px solid color-mix(in oklab, currentColor 30%, transparent);
  background: color-mix(in oklab, currentColor 10%, transparent);
}

.brand {
  background: #ff6a00; /* fallback (sRGB) */
  background: color(display-p3 1 0.42 0); /* P3 ディスプレイ */
}
